function generarDesafioFarma() {
    let filtrados = BANCO_DESAFIOS_FARMACOLOGIA;
    if (familiaFarmaActiva !== "todas") {
        const porFam = filtrados.filter(d => d.familia === familiaFarmaActiva);
        if (porFam.length > 0) filtrados = porFam;
    }
    const porDiff = filtrados.filter(d => d.dificultad === dificultadFarmaActiva);
    if (porDiff.length > 0) filtrados = porDiff;

    const desafio = filtrados[Math.floor(Math.random() * filtrados.length)] || BANCO_DESAFIOS_FARMACOLOGIA[0];
    casoFarmaActivoActual = desafio;

    const pdfsFarma = estadoMultiPdfMedicina.farma || [];
    let customNotice = "";
    if (pdfsFarma.length > 0) {
        customNotice = `<br><span style="display:inline-block;margin-top:0.35rem;font-size:0.75rem;color:#c084fc;">💊 Contrastado con tus textos de Farma: ${pdfsFarma.map(d => d.name).join(", ")}</span>`;
    }

    const cId = document.getElementById("farmaCaseId");
    const cMeta = document.getElementById("farmaCaseMeta");
    const diffBadge = document.getElementById("farmaDiffBadge");
    const cText = document.getElementById("farmaCaseText");
    const labList = document.getElementById("farmaCaseLabList");
    const qList = document.getElementById("farmaQuestionsList");
    const discPanel = document.getElementById("farmaDiscussionPanel");
    const discContent = document.getElementById("farmaDiscussionContent");
    const revealBtn = document.getElementById("farmaRevealDiscussionBtn");

    if (cId) cId.textContent = `${desafio.id} · ${desafio.subtitulo}`;
    if (cMeta) cMeta.innerHTML = `Desafío Farmacoterapéutico Universitario${customNotice}`;
    if (diffBadge) {
        const labels = { 1: "Nivel 1: Cinética & Diana", 2: "Nivel 2: Ajuste & Interacciones", 3: "Nivel 3: Toxicología & Crisis" };
        diffBadge.textContent = labels[desafio.dificultad] || "Desafío Farmacológico";
    }
    if (cText) cText.textContent = desafio.texto;
    if (labList && desafio.laboratorio) {
        labList.innerHTML = desafio.laboratorio.map(it => `<li>${it}</li>`).join("");
    }
    if (qList && desafio.preguntas) {
        qList.innerHTML = desafio.preguntas.map(it => `<li>${it}</li>`).join("");
    }
    if (discContent) {
        discContent.innerHTML = desafio.discusion;
    }
    if (discPanel) discPanel.classList.add("hidden");
    if (revealBtn) revealBtn.textContent = "💡 Revelar Análisis Farmacoterapéutico";

    // Limpiar notas previas y feedback de IA
    const notesInput = document.getElementById("farmaStudentNotes");
    if (notesInput) notesInput.value = "";
    const fbPanel = document.getElementById("farmaAiEvaluationFeedback");
    if (fbPanel) {
        fbPanel.classList.add("hidden");
        fbPanel.innerHTML = "";
    }

    mostrarToast(`🧪 Desafío generado: ${desafio.id}`, "exito");
}

/* ==========================================================
   MOTOR DE EVALUACIÓN DIAGNÓSTICA CON IA CLÍNICA (GEMINI PRO)
   ========================================================== */
async function evaluarDiagnosticoConIA(materia = "interna") {
    const esFarma = materia === "farma";
    const esShock = materia === "shock";
    const inputElem = document.getElementById(
        esShock ? "shockStudentDiagnosisInput" : (esFarma ? "farmaStudentNotes" : "medStudentDiagnosisInput")
    );
    const btnElem = document.getElementById(
        esShock ? "shockSubmitDiagnosisBtn" : (esFarma ? "farmaSubmitDiagnosisBtn" : "medSubmitDiagnosisBtn")
    );
    const feedbackPanel = document.getElementById(
        esShock ? "shockAiFeedbackPanel" : (esFarma ? "farmaAiEvaluationFeedback" : "medAiEvaluationFeedback")
    );

    const textoEstudiante = (inputElem?.value || "").trim();
    if (!textoEstudiante) {
        mostrarToast("✍️ Por favor escribí tu resolución o planteo terapéutico en el recuadro antes de enviar.", "advertencia");
        if (inputElem) {
            inputElem.focus();
            inputElem.scrollIntoView({ behavior: "smooth", block: "center" });
            inputElem.style.borderColor = "#c084fc";
            inputElem.style.boxShadow = "0 0 16px rgba(192, 132, 252, 0.5)";
            setTimeout(() => {
                inputElem.style.borderColor = "";
                inputElem.style.boxShadow = "";
            }, 2500);
        }
        return;
    }

    let casoActivo = esShock ? casoShockRoomActivo : (esFarma ? casoFarmaActivoActual : casoInternaActivoActual);
    if (!casoActivo) {
        if (esShock) {
            casoShockRoomActivo = BANCO_CASOS_SHOCK_ROOM[0];
            casoActivo = casoShockRoomActivo;
        } else if (esFarma) {
            casoFarmaActivoActual = BANCO_DESAFIOS_FARMACOLOGIA[0];
            casoActivo = casoFarmaActivoActual;
        } else {
            casoInternaActivoActual = BANCO_CASOS_INTERNA_AVANZADOS[0];
            casoActivo = casoInternaActivoActual;
        }
    }

    const textoOriginalBoton = btnElem ? btnElem.innerHTML : "";
    if (btnElem) {
        btnElem.disabled = true;
        btnElem.innerHTML = `<i class="fas fa-spinner fa-spin"></i> Evaluando con IA Médica...`;
    }

    if (feedbackPanel) {
        feedbackPanel.classList.remove("hidden");
        feedbackPanel.innerHTML = `
            <div class="med-ai-feedback-loading">
                <i class="fas fa-brain fa-spin"></i>
                <div style="font-weight:600;font-size:0.95rem;">Profesor Virtual Evaluando Razonamiento Clínico...</div>
                <div style="font-size:0.8rem;color:#94a3b8;margin-top:0.35rem;">Analizando concordancia nosológica, fisiopatología y farmacovigilancia.</div>
            </div>
        `;
        feedbackPanel.scrollIntoView({ behavior: "smooth", block: "nearest" });
    }

    let resultadoFinal = null;

    try {
        let casoTexto = "";
        if (esShock) {
            casoTexto = `${casoActivo.id} (${casoActivo.cama}): ${casoActivo.titulo}. Motivo de Ingreso: ${casoActivo.motivoIngreso}. Signos Vitales: FC ${casoActivo.signosVitales?.fc} lpm, PA ${casoActivo.signosVitales?.pa}, SpO2 ${casoActivo.signosVitales?.spo2}%, FR ${casoActivo.signosVitales?.fr}, Temp ${casoActivo.signosVitales?.temp}°C, Glasgow ${casoActivo.signosVitales?.glasgow}. Laboratorio: ${(casoActivo.laboratorio || []).map(l => `${l.parametro}: ${l.valor} (${l.alerta})`).join(" | ")}. Rx: ${casoActivo.estudios?.radiografia?.hallazgos || ""}. TC: ${casoActivo.estudios?.tomografia?.hallazgos || ""}. ECG: ${casoActivo.estudios?.ecg?.hallazgos || ""}.`;
        } else if (esFarma) {
            casoTexto = `${casoActivo.id}: ${casoActivo.subtitulo}. Enunciado: ${casoActivo.texto}. Laboratorio: ${(casoActivo.laboratorio || []).join(" | ")}.`;
        } else {
            casoTexto = `${casoActivo.id} (${casoActivo.cama}): ${casoActivo.titulo}. Motivo de Ingreso: ${casoActivo.cuadro || casoActivo.enfermedadActual || ""}. Laboratorio: ${(casoActivo.laboratorio || []).map(l => typeof l === 'string' ? l : `${l.c1 || ''} ${l.c2 || ''}`).join(" | ")}. Examen: ${Array.isArray(casoActivo.examenFisico) ? casoActivo.examenFisico.join(" | ") : (casoActivo.examenFisico || "")}.`;
        }

        const payload = {
            tipoJuego: "evaluacion_clinica",
            materia: esShock ? "Shock Room / Medicina de Emergencias" : (esFarma ? "Farmacología 2" : "Medicina Interna"),
            casoClinico: casoTexto,
            diagnosticoOficial: (casoActivo.diagnosticoOficial || casoActivo.discusion || "").replace(/<[^>]*>?/gm, " "),
            diagnosticoEstudiante: textoEstudiante
        };

        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 14000);

        const response = await fetch("/api/gemini", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
            signal: controller.signal
        });
        clearTimeout(timeoutId);

        if (response.ok) {
            const data = await response.json();
            if (data && typeof data.puntaje === "number") {
                resultadoFinal = data;
            }
        }
    } catch (err) {
        console.warn("[Evaluador Clínico IA] Fallback a evaluación semántica local:", err);
    }

    if (!resultadoFinal) {
        resultadoFinal = evaluarDiagnosticoClinicoLocal(casoActivo, textoEstudiante, materia);
    }

    if (feedbackPanel) {
        renderizarResultadoEvaluacionIA(feedbackPanel, resultadoFinal);
    }

    if (btnElem) {
        btnElem.disabled = false;
        btnElem.innerHTML = textoOriginalBoton;
    }

    mostrarToast(`Evaluación completada: ${resultadoFinal.puntaje}/100 pts`, resultadoFinal.puntaje >= 60 ? "exito" : "advertencia");
}

function renderizarResultadoEvaluacionIA(container, data) {
    if (!container || !data) return;

    const esAprobado = (data.puntaje || 0) >= 60;
    const badgeClass = esAprobado ? "score-badge--pass" : "score-badge--fail";
    const estadoIcon = data.diagnosticoCorrecto ? "fa-circle-check" : "fa-triangle-exclamation";
    const estadoColor = data.diagnosticoCorrecto ? "#22c55e" : "#f59e0b";

    const aciertosHtml = (data.aciertos && data.aciertos.length > 0)
        ? data.aciertos.map(a => `<li><i class="fas fa-check" style="color:#22c55e;margin-right:0.4rem;"></i>${a}</li>`).join("")
        : `<li>Aproximación inicial registrada.</li>`;

    const erroresHtml = (data.erroresUOmitidos && data.erroresUOmitidos.length > 0)
        ? data.erroresUOmitidos.map(e => `<li><i class="fas fa-exclamation-triangle" style="color:#f59e0b;margin-right:0.4rem;"></i>${e}</li>`).join("")
        : `<li>Sin omisiones críticas detectadas en el planteo.</li>`;

    container.innerHTML = `
        <div class="med-ai-feedback-header">
            <div style="display:flex;align-items:center;gap:0.75rem;">
                <i class="fas ${estadoIcon}" style="font-size:1.6rem;color:${estadoColor};"></i>
                <div>
                    <h4 style="margin:0;font-size:1.05rem;color:#f8fafc;">${data.veredicto || "Dictamen de Cátedra"}</h4>
                    <span style="font-size:0.75rem;color:#94a3b8;">Evaluación estructurada por Inteligencia Artificial Médica</span>
                </div>
            </div>
            <div class="score-badge ${badgeClass}">
                <span class="score-number">${data.puntaje || 0}</span>
                <span class="score-label">/ 100</span>
            </div>
        </div>

        <div class="med-ai-critique-box">
            <strong><i class="fas fa-microscope" style="color:#60a5fa;margin-right:0.35rem;"></i>Análisis Fisiopatológico y Razonamiento:</strong>
            <p style="margin:0.4rem 0 0 0;font-size:0.88rem;color:#cbd5e1;line-height:1.5;">${data.analisisFisiopatologico || "Evaluación clínica completada con éxito."}</p>
        </div>

        <div class="med-ai-lists-grid">
            <div class="med-ai-list-card med-ai-list-card--success">
                <span class="med-ai-list-title"><i class="fas fa-thumbs-up"></i> Aciertos y Fortalezas:</span>
                <ul>${aciertosHtml}</ul>
            </div>
            <div class="med-ai-list-card med-ai-list-card--warning">
                <span class="med-ai-list-title"><i class="fas fa-shield-virus"></i> Oportunidades y Omisiones:</span>
                <ul>${erroresHtml}</ul>
            </div>
        </div>

        ${data.conductaTerapeuticaSugerida ? `
            <div style="background:rgba(59,130,246,0.08);border:1px solid rgba(59,130,246,0.25);border-radius:10px;padding:0.75rem 1rem;margin-top:0.8rem;font-size:0.85rem;color:#93c5fd;">
                <strong><i class="fas fa-pills" style="margin-right:0.35rem;"></i>Conducta Terapéutica Sugerida:</strong> ${data.conductaTerapeuticaSugerida}
            </div>
        ` : ""}

        ${data.consejoDocente ? `
            <div style="margin-top:0.75rem;padding:0.6rem 0.85rem;border-left:3px solid #c084fc;background:rgba(192,132,252,0.08);font-size:0.82rem;color:#e9d5ff;border-radius:0 8px 8px 0;">
                <strong><i class="fas fa-user-doctor" style="margin-right:0.35rem;"></i>Consejo del Docente:</strong> "${data.consejoDocente}"
            </div>
        ` : ""}
    `;
    container.classList.remove("hidden");
    container.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function evaluarDiagnosticoClinicoLocal(caso, textoEstudiante, materia) {
    const textoNorm = (textoEstudiante || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    const nombreCaso = caso.titulo || caso.subtitulo || "Caso Clínico";

    // 1. Extracción y análisis de conceptos clave de la resolución oficial
    const discusionLimpia = (caso.discusion || "").replace(/<[^>]*>?/gm, " ").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    const palabrasClave = discusionLimpia.match(/\b[a-z]{5,}\b/g) || [];
    
    const stopWords = new Set([
        "porque", "cuando", "donde", "paciente", "cuadro", "clinico", "administracion",
        "tratamiento", "presenta", "ademas", "durante", "produce", "debido", "inmediata",
        "deberia", "primer", "segundo", "tercer", "pueden", "generar", "llevar", "cuanto",
        "tiempo", "forma", "horas", "dias", "nivel", "niveles"
    ]);
    const terminosImportantes = [...new Set(palabrasClave.filter(w => !stopWords.has(w)))];

    // Contar coincidencias reales
    let coincidencias = 0;
    const aciertosDetectados = [];
    terminosImportantes.forEach(t => {
        if (textoNorm.includes(t)) {
            coincidencias++;
            if (aciertosDetectados.length < 4) {
                aciertosDetectados.push(`Mención precisa del concepto fisiopatológico / farmacológico: "${t}"`);
            }
        }
    });

    // Detección de hipótesis descabelladas, sin correlato o frases de prueba
    const tieneCancer = textoNorm.includes("cancer") || textoNorm.includes("oncolog") || textoNorm.includes("tumor");
    const esCasoCancer = discusionLimpia.includes("cancer") || discusionLimpia.includes("oncolog") || discusionLimpia.includes("tumor");
    const diceMuerte = textoNorm.includes("morir") || textoNorm.includes("muerte") || textoNorm.includes("letal");

    // 2. CASO CERO ACIERTOS / ERROR CRÍTICO O DIAGNÓSTICO DISPARATADO (0/100)
    if (coincidencias === 0) {
        let motivoCritica = `Tu planteo ('"${textoEstudiante.length > 70 ? textoEstudiante.substring(0, 67) + "..." : textoEstudiante}"') NO guarda ninguna relación con la presentación clínica, los signos vitales ni el laboratorio de este paciente.`;
        if (tieneCancer && !esCasoCancer) {
            motivoCritica += ` Diagnosticaste patología oncológica ("cáncer") en un paciente que no presenta ningún antecedente, síndrome consuntivo ni biopsia que lo sugiera.`;
        }
        if (diceMuerte) {
            motivoCritica += ` Afirmar fatalidad ("se va a morir") sin formular una hipótesis nosológica ni una intervención terapéutica constituye una conducta inaceptable en la práctica médica.`;
        }
        motivoCritica += ` El paciente presenta en realidad: <strong>${nombreCaso}</strong>. En un hospital real o examen universitario, este planteo implicaría desaprobación fulminante por riesgo iatrogénico.`;

        return {
            diagnosticoCorrecto: false,
            puntaje: 0,
            veredicto: "Desacierto Diagnóstico Total / Error Crítico (0/100)",
            analisisFisiopatologico: motivoCritica,
            aciertos: [
                "Ninguno. No se identificó la patología del caso ni se formularon medidas terapéuticas válidas."
            ],
            erroresUOmitidos: [
                "Diagnóstico completamente erróneo sin correlación clínica ni paraclínica",
                "Omisión absoluta de los valores de laboratorio y electrocardiograma aportados",
                "Falta de indicación de medidas de soporte vital y rescate farmacológico real",
                tieneCancer && !esCasoCancer ? "Presunción infundada de neoplasia sin evidencia" : "Inconsistencia nosológica grave"
            ],
            conductaTerapeuticaSugerida: caso.discusion ? caso.discusion.replace(/<[^>]*>?/gm, " ").substring(0, 260) + "..." : "Consultar resolución oficial de cátedra.",
            consejoDocente: "Dr. Iván: La cátedra exige rigurosidad científica implacable. Un médico jamás puede adivinar o diagnosticar por intuición sin contrastar los datos. Antes de emitir una conducta, lee los antecedentes, el examen físico y el laboratorio."
        };
    }

    // 3. APROXIMACIÓN MUY INSUFICIENTE (1 coincidencia aislada - 25/100)
    if (coincidencias === 1) {
        return {
            diagnosticoCorrecto: false,
            puntaje: 25,
            veredicto: "Aproximación Muy Insuficiente (25/100)",
            analisisFisiopatologico: `Identificaste únicamente un término aislado (${aciertosDetectados[0]}), pero careces de desarrollo fisiopatológico. No se articula la relación de causa-efecto ni el protocolo terapéutico de primera línea para ${nombreCaso}.`,
            aciertos: aciertosDetectados,
            erroresUOmitidos: [
                "Falta de formulación del síndrome cardinal completo",
                "Omisión del mecanismo farmacológico o diana molecular principal",
                "Plan terapéutico incompleto o insuficiente para estabilizar al paciente"
            ],
            conductaTerapeuticaSugerida: materia === "farma"
                ? "Identificar el transportador/enzima afectada, ajustar según clearance y dosificar el antídoto específico."
                : "Monitoreo invasivo continuo y terapia etiológica dirigida según guías clínicas.",
            consejoDocente: "Dr. Iván: Nombrar un concepto no alcanza para aprobar un pase de sala. Necesitás fundamentar el por qué y el tratamiento de rescate inmediato."
        };
    }

    // 4. ENFOQUE PARCIAL (2 coincidencias - 50/100)
    if (coincidencias === 2) {
        return {
            diagnosticoCorrecto: false,
            puntaje: 50,
            veredicto: "Enfoque Parcial / Insuficiente para Criterio de Alta (50/100)",
            analisisFisiopatologico: `Demuestras orientación general hacia ${nombreCaso}, pero con omisiones determinantes en la farmacovigilancia o en las contraindicaciones críticas del paciente.`,
            aciertos: aciertosDetectados,
            erroresUOmitidos: [
                "Falta precisar interacciones farmacocinéticas o ajustes orgánicos",
                "Monitoreo de parámetros de seguridad pendientes"
            ],
            conductaTerapeuticaSugerida: "Profundizar en la conducta razonada de cátedra y dosificación protocolizada.",
            consejoDocente: "Dr. Iván: Buen inicio del razonamiento, pero en la práctica estas omisiones pueden generar descompensación. Ajustá la farmacocinética fina."
        };
    }

    // 5. DIAGNÓSTICO CERTERO Y SÓLIDO (3 a 4 coincidencias - 78/100)
    if (coincidencias < 5) {
        return {
            diagnosticoCorrecto: true,
            puntaje: 78,
            veredicto: "Diagnóstico Certero con Buen Razonamiento Clínico (78/100)",
            analisisFisiopatologico: `¡Muy buen planteo! Identificaste los factores determinantes de ${nombreCaso}. Tu conducta terapéutica es coherente con las guías de cátedra.`,
            aciertos: aciertosDetectados,
            erroresUOmitidos: [
                "Podrías afinar detalles sobre la ventana de monitoreo o dosis exactas"
            ],
            conductaTerapeuticaSugerida: materia === "farma"
                ? "Ajustar dosis según función renal/hepática y verificar interacciones con la medicación de base."
                : "Medidas de soporte hemodinámico y tratamiento de rescate según normativas vigentes.",
            consejoDocente: "Excelente criterio diagnóstico, colega. Mantén este estándar de fundamentación en cada pase de guardia."
        };
    }

    // 6. RESOLUCIÓN DE EXCELENCIA (5+ coincidencias - 95/100)
    return {
        diagnosticoCorrecto: true,
        puntaje: 95,
        veredicto: "Resolución de Excelencia · Nivel Médico de Planta (95/100)",
        analisisFisiopatologico: `Resolución impecable. Dominas la fisiopatología, las dianas moleculares, la interacción farmacocinética y la conducta de rescate para ${nombreCaso}.`,
        aciertos: aciertosDetectados,
        erroresUOmitidos: [
            "Sin omisiones de relevancia clínica detectadas en tu desarrollo"
        ],
        conductaTerapeuticaSugerida: "Conducta óptima aplicada.",
        consejoDocente: "Brillante, Dr. Iván. Un análisis exhaustivo y de máxima solvencia que salvaría la vida del paciente en un escenario real."
    };
}

